"use client";

import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { X } from "lucide-react";
import { PlaceholdersAndVanishInput } from "@/components/ui/placeholders-and-vanish-input";

interface StatusUpdate {
  id: string;
  user: string;
  status: string;
  time: string;
  avatar: string;
  media?: string;
  type: "image" | "video";
}

interface StatusWindowProps {
  statusUpdates: StatusUpdate[];
}

const StatusWindow: React.FC<StatusWindowProps> = ({ statusUpdates }) => {
  const [selectedStatusIndex, setSelectedStatusIndex] = useState<number | null>(null);
  const [isChatOpen, setIsChatOpen] = useState(false);  // 🔹 Chat window state

  useEffect(() => {
    if (selectedStatusIndex !== null) {
      const timer = setTimeout(() => {
        if (selectedStatusIndex < statusUpdates.length - 1) {
          setSelectedStatusIndex(selectedStatusIndex + 1);
        } else {
          setSelectedStatusIndex(null);
        }
      }, 5000);

      return () => clearTimeout(timer);
    }
  }, [selectedStatusIndex]);

  return (
    <div className="p-4 bg-gray-900 border-t border-gray-700">
      <h2 className="text-lg font-semibold text-gray-200 mb-4">Status Updates</h2>
      <div className="flex gap-4 overflow-x-auto">
        {statusUpdates.map((status, index) => (
          <div
            key={status.id}
            className="cursor-pointer flex flex-col items-center"
            onClick={() => setSelectedStatusIndex(index)}
          >
            <motion.div whileHover={{ scale: 1.1 }} className="w-16 h-16 rounded-full border-4 border-green-500 p-1">
              <img src={status.avatar} alt={status.user} className="w-full h-full rounded-full" />
            </motion.div>
            <p className="text-xs text-gray-400 mt-1">{status.time}</p>
          </div>
        ))}
      </div>

      <AnimatePresence>
        {selectedStatusIndex !== null && !isChatOpen && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed top-0 left-0 w-full h-screen bg-black bg-opacity-90 flex items-center justify-center z-50"
          >
            <div className="relative w-[90%] max-w-lg bg-black rounded-lg shadow-lg">
              <button
                onClick={() => setSelectedStatusIndex(null)}
                className="absolute top-3 right-3 text-white bg-gray-800 p-2 rounded-full"
              >
                <X className="w-5 h-5" />
              </button>
              <div className="absolute top-3 left-3 right-3 h-1 bg-gray-700 rounded-full overflow-hidden">
                <motion.div
                  initial={{ width: "0%" }}
                  animate={{ width: "100%" }}
                  transition={{ duration: 5, ease: "linear" }}
                  className="h-full bg-green-500"
                />
              </div>
              <div className="p-5 flex flex-col h-screen w-full items-center">
                {statusUpdates[selectedStatusIndex].type === "video" ? (
                  <video src={statusUpdates[selectedStatusIndex].media} className="w-full rounded-lg h-full object-cover" autoPlay loop controls />
                ) : (
                  <img src={statusUpdates[selectedStatusIndex].media} alt="Status" className="w-full rounded-lg h-full object-cover" />
                )}

                <p className="text-gray-200 text-lg mt-4">{statusUpdates[selectedStatusIndex].status}</p>

                {/* 🔹 New Button to Open Chat */}
                <button 
                  onClick={() => setIsChatOpen(true)}  
                  className="mt-4 px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600"
                >
                  Message {statusUpdates[selectedStatusIndex].user}
                </button>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
      <AnimatePresence>
        {isChatOpen && (
          <motion.div
            initial={{ opacity: 0, y: 100 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 100 }}
            className="fixed bottom-0 left-1/2 transform -translate-x-1/2 w-[400px] h-[500px] bg-gray-800 shadow-lg rounded-lg flex flex-col z-50"
          >
            <div className="p-4 bg-gray-900 text-white flex justify-between items-center">
              <h3 className="text-lg font-semibold">Chat with {statusUpdates[selectedStatusIndex]?.user}</h3>
              <button onClick={() => setIsChatOpen(false)} className="text-gray-400 hover:text-white">
                <X className="w-6 h-6" />
              </button>
            </div>
            <div className="flex-1 p-4 overflow-y-auto">
              <div className="mb-2 p-2 bg-gray-700 rounded-lg w-max text-white">Hey there! 👋</div>
              <div className="mb-2 p-2 bg-blue-500 rounded-lg w-max ml-auto text-white">Hello! 😊</div>
            </div>
            <div className="p-4 border-t border-gray-700">
              <PlaceholdersAndVanishInput placeholders={["Type a message..."]} />
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default StatusWindow;
